const item = $input.first().json;
const body = item.body || {};
const required = ['phone','crop','market','data_month','recommendation'];
for (const field of required) { if (typeof body[field] !== 'string' || !body[field].trim()) { throw new Error('Missing field: ' + field); } }
if (!/^\+[1-9]\d{7,14}$/.test(body.phone)) { throw new Error('Invalid international phone format'); }
const allowed = ['Maize','Rice','Beans'];
if (!allowed.includes(body.crop)) { throw new Error('Unsupported crop'); }
return [{ json: { acknowledged: true, delivery_status: 'not_configured', is_demo: true, crop: body.crop, market: body.market, message: body.recommendation, note: 'No SMS sent: install/configure an SMS provider node before claiming delivery.' } }];
